<script setup lang="ts">
const props=defineProps<{csrf:string,date?:string}>()
const emit=defineEmits(['saved'])
const form=ref<any>({kind:'wellness',date:props.date||new Date().toLocaleDateString('sv-SE'),fatigue:'',soreness:'',motivation:'',recovery:'',sleep_quality:'',rpe:'',notes:'',declared_rest:false})
watch(()=>props.date,v=>{if(v)form.value.date=v})
const labels:any={fatigue:'Fatica',soreness:'Indolenzimento',motivation:'Motivazione',recovery:'Recupero percepito',sleep_quality:'Qualità sonno percepita',rpe:'RPE della giornata'}
const preview=ref<any>(null),message=ref(''),busy=ref(false)
async function submit(confirm=false){busy.value=true;message.value='';try{const result=await $fetch<any>('/api/platform/memory',{method:'POST',headers:{'x-csrf-token':props.csrf},body:confirm?{kind:'wellness',confirm:true,preview_token:preview.value.preview_token}:form.value});if(confirm){preview.value=null;message.value='Feedback salvato.';emit('saved')}else preview.value=result}catch(e:any){message.value=e.data?.error||'Feedback non salvato'}finally{busy.value=false}}
</script>
<template><div><h3 class="font-semibold mb-3">Le tue sensazioni completano i dati</h3><p class="muted mb-4">Scale 0–10: fatica e indolenzimento crescono con la difficoltà; motivazione, recupero e qualità del sonno crescono con il benessere. Lascia vuoto ciò che non vuoi valutare.</p><input type="date" v-model="form.date" aria-label="Data feedback"/><div class="grid grid-cols-2 sm:grid-cols-3 gap-3 mt-4"><label v-for="(label,key) in labels" :key="key" class="text-xs text-zinc-400">{{label}}<select v-model="form[key]" class="w-full mt-1" :aria-label="label"><option value="">Non valutato</option><option v-for="n in 11" :value="n-1">{{n-1}}</option></select></label></div><textarea v-model="form.notes" rows="3" placeholder="Contesto, lavoro, attrezzi, sensazioni…" aria-label="Note soggettive" class="w-full mt-4"/><label class="flex gap-2 text-sm mt-3"><input type="checkbox" v-model="form.declared_rest"/>Ho programmato una giornata di riposo</label><UButton class="mt-4" @click="submit()" :loading="busy">Anteprima feedback</UButton><div v-if="preview" class="mt-4 rounded-lg border border-green-800 p-4"><p class="font-semibold">{{preview.preview.date}} · conferma le valutazioni</p><p v-for="(label,key) in labels" class="muted mt-1">{{label}}: {{preview.preview[key]??'non valutato'}}</p><p class="muted mt-2">{{preview.preview.notes}}</p><UButton class="mt-4" @click="submit(true)" :loading="busy">Conferma feedback</UButton></div><p role="status" class="muted mt-3">{{message}}</p></div></template>
